// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the array length and a value to send; we also fuzz an arbitrary address but will deploy helpers
    function testFuzz_property(uint8 tosLen, uint256 v) public {
        // keep domain reasonable but wide: require at least 1 element to hit require(_tos.length > 0)
        vm.assume(tosLen > 0);
        // construct tos array of addresses all pointing to a helper that returns success
        address[] memory tos = new address[](tosLen);
        // deploy a helper that always returns success for transferFrom signature
        RecorderSuccess helperSuccess = new RecorderSuccess();
        for (uint i = 0; i < tosLen; i++) tos[i] = address(helperSuccess);

        // Call reference contract and observe it does not revert and returns true
        bool ok;
        try c.transfer(address(0xBEEF), address(helperSuccess), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any non-empty tos, when the callee returns success on each call, the reference finishes (ok==true).
        // The mutant inverts the require on the callee success and will revert when callee returns success; thus
        // there exist inputs (tosLen>0, callee that returns success) that make mutant revert while reference does not.
        assertTrue(ok);

        // Also assert the helper recorded the expected number of calls (visibility into external calls)
        // This ensures the reference actually invoked the external callee tosLen times.
        assertTrue(helperSuccess.callCount() == tosLen);
    }
}

// Helper that implements transferFrom(address,address,uint256) and RETURNS success (true)
contract RecorderSuccess {
    uint public callCount;
    // match selector: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        callCount += 1;
        return true;
    }
}
